<?php
namespace App\Services;
use App\Models\{Pelanggan,PromoMember,PromoRedemption,Transaksi};
use Illuminate\Support\Facades\DB;
use RuntimeException;
class PromoEngineService
{
 public function calculate(PromoMember $promo,float $subtotal,string $scope,Pelanggan $customer):array{$subtotal=max(0,(int)round($subtotal));if(!$promo->isVisibleAt()||$promo->status!=='aktif')throw new RuntimeException('Promo tidak aktif.');if($promo->berlaku_untuk!=='semua'&&$promo->berlaku_untuk!==$scope)throw new RuntimeException('Promo tidak berlaku untuk transaksi ini.');if($subtotal<(float)$promo->minimum_transaksi)throw new RuntimeException('Minimum transaksi promo belum terpenuhi.');if($promo->member_only&&(!$customer->membership||!$customer->membership->isActive()))throw new RuntimeException('Promo hanya untuk YZA Member aktif.');$used=PromoRedemption::where('id_promo',$promo->id_promo)->where('id_pelanggan',$customer->id_pelanggan)->where('status','completed')->count();if($promo->usage_per_member!==null&&$used>=$promo->usage_per_member)throw new RuntimeException('Batas penggunaan promo per member sudah tercapai.');$all=PromoRedemption::where('id_promo',$promo->id_promo)->where('status','completed')->count();if($promo->quota!==null&&$all>=$promo->quota)throw new RuntimeException('Kuota promo sudah habis.');$raw=$promo->jenis_benefit==='persentase'?intdiv($subtotal*(int)round((float)$promo->nilai_benefit*100),10000):(int)round((float)$promo->nilai_benefit);$discount=$promo->maksimum_benefit!==null?min($raw,(int)round((float)$promo->maksimum_benefit)):$raw;$discount=max(0,min($subtotal,$discount));return['promo_id'=>$promo->id_promo,'promo_code'=>$promo->kode_promo,'promo_name'=>$promo->nama,'subtotal'=>$subtotal,'discount_type'=>$promo->jenis_benefit,'discount_value'=>(float)$promo->nilai_benefit,'discount'=>$discount,'max_discount_applied'=>$discount<$raw,'total_final'=>$subtotal-$discount,'scope'=>$scope,'eligible'=>true,'calculated_at'=>now()->toISOString()];}
 public function applyToTransaction(Transaksi $transaction,int $promoId,string $scope):array{return DB::transaction(function()use($transaction,$promoId,$scope):array{$tx=Transaksi::lockForUpdate()->findOrFail($transaction->id_transaksi);if($tx->id_promo!==null)throw new RuntimeException('Satu transaksi hanya boleh memakai satu promo.');$customer=Pelanggan::with('membership')->findOrFail($tx->id_pelanggan);$promo=PromoMember::lockForUpdate()->findOrFail($promoId);$result=$this->calculate($promo,(float)$tx->subtotal,$scope,$customer);$tx->forceFill(['id_promo'=>$promo->id_promo,'promo_code_snapshot'=>$promo->kode_promo,'promo_name_snapshot'=>$promo->nama,'promo_type_snapshot'=>$promo->jenis_benefit,'promo_value_snapshot'=>$promo->nilai_benefit,'diskon'=>$result['discount'],'total'=>$result['total_final']])->save();return$result;});}
 public function finalizeRedemption(Transaksi $transaction):?PromoRedemption{return DB::transaction(function()use($transaction):?PromoRedemption{$tx=Transaksi::lockForUpdate()->findOrFail($transaction->id_transaksi);if(!$tx->id_promo||$tx->status!=='lunas'||!$tx->id_pelanggan)return null;$existing=PromoRedemption::where('id_transaksi',$tx->id_transaksi)->lockForUpdate()->first();if($existing?->status==='completed')return$existing;$promo=PromoMember::lockForUpdate()->findOrFail($tx->id_promo);$customer=Pelanggan::with('membership')->findOrFail($tx->id_pelanggan);$used=PromoRedemption::where('id_promo',$promo->id_promo)->where('status','completed')->lockForUpdate()->count();$memberUsed=PromoRedemption::where('id_promo',$promo->id_promo)->where('id_pelanggan',$customer->id_pelanggan)->where('status','completed')->count();if(($promo->quota!==null&&$used>=$promo->quota)||($promo->usage_per_member!==null&&$memberUsed>=$promo->usage_per_member))throw new RuntimeException('Kuota promo tidak tersedia saat pembayaran diselesaikan.');return PromoRedemption::updateOrCreate(['id_transaksi'=>$tx->id_transaksi],['id_promo'=>$promo->id_promo,'id_pelanggan'=>$customer->id_pelanggan,'subtotal'=>$tx->subtotal,'discount'=>$tx->diskon,'total_final'=>$tx->total,'used_at'=>now(),'status'=>'completed']);});}
 public function redeem(PromoMember $promo,Transaksi $transaction,Pelanggan $customer,string $scope):PromoRedemption{return DB::transaction(function()use($promo,$transaction,$customer,$scope):PromoRedemption{$locked=PromoMember::lockForUpdate()->findOrFail($promo->id_promo);$calc=$this->calculate($locked,(float)$transaction->subtotal,$scope,$customer);return PromoRedemption::updateOrCreate(['id_promo'=>$locked->id_promo,'id_transaksi'=>$transaction->id_transaksi],['id_pelanggan'=>$customer->id_pelanggan,'subtotal'=>$calc['subtotal'],'discount'=>$calc['discount'],'total_final'=>$calc['total_final'],'used_at'=>now(),'status'=>'completed']);});}
}
